commands.stdout:
#!/sbin/openrc-run

name="appsvc-webapp"
description="Rootless podman webapp container running as appsvc"

depend() {
    need cgroups
    need net
    after networking
}

start() {
    ebegin "Starting appsvc webapp container"
    su appsvc -s /bin/sh -c "podman start webapp"
    eend $?
}

stop() {
    ebegin "Stopping appsvc webapp container"
    su appsvc -s /bin/sh -c "podman stop webapp"
    eend $?
}

status() {
    if su appsvc -s /bin/sh -c "podman inspect -f '{{.State.Running}}' webapp" 2>/dev/null | grep -q true; then
        einfo "status: started"
    else
        einfo "status: stopped"
        return 1
    fi
}
